-- 1. 先确认未分析的表（只读）：
SELECT schemaname, tablename, last_analyze, n_live_tup FROM pg_stat_user_tables WHERE last_analyze IS NULL ORDER BY n_live_tup DESC LIMIT 20;
-- 2. 建议非高峰执行（谨慎）：
-- DANGER: ANALYZE <SCHEMA>.<TABLE>;

-- 未授权的锁（只读）：
SELECT * FROM pg_locks WHERE NOT granted;
-- 正在等锁的线程（只读）：
SELECT * FROM pg_thread_wait_status WHERE wait_status = 'acquire lock';

-- 1. 先确认（只读，华为云官方示例）：
SELECT datname, usename, state, pid FROM pg_stat_activity WHERE pid = <PID>;
-- 2. 确认无误后再执行（危险，华为云官方示例）：
-- DANGER: SELECT pg_terminate_backend(<PID>);

-- 1. 列出全部表空间（只读）：
SELECT spcname FROM pg_tablespace;
-- 2. 单个表空间已用字节（只读，单位字节）：
SELECT pg_tablespace_size('<TABLESPACE>') AS size_bytes;
